mapper.update:
update integration_schema.job_run set status=#{status},error_code=#{code},error_summary=#{summary},
  next_retry_at=case when #{retry} then clock_timestamp()+(#{delay} * interval '1 second') else null end,
  finished_at=case when #{retry} then null else clock_timestamp() end where run_id=#{runId}

mapper.select:
select count(*) from integration_schema.job_run
where status in ('PENDING','RUNNING','RETRY_WAIT','CANCEL_REQUESTED')
and job_code=#{jobCode}

select * from integration_schema.job_run
job_code=#{jobCode}
order by created_at desc limit #{size} offset #{offset}
